# (verdes y rojas) en memoria/.colores_de_antes.json, ruta -> 'verde' o 'roja'.
# Una roja de ahora solo frena si en ese archivo figuraba como VERDE: las rojas
# que ya estaban rojas antes no frenan. No se toca .rojas_conocidas.json.
colores_de_antes = {}
try:
    ruta_colores = os.path.join(raiz, "memoria", ".colores_de_antes.json")
    with open(ruta_colores, encoding="utf-8") as f:
        leidos = json.load(f)
    if isinstance(leidos, dict):
        colores_de_antes = leidos
except Exception:
    colores_de_antes = {}
guardados_que_frenan = rojas_que_frenan(archivos_rojos, guardados, list(esperando), colores_de_antes)

# Todos los rojos son nuevos o esperan su arreglo: dejar pasar con aviso.
# Se actualiza el color de antes SOLO si ningun grupo se corto por tiempo: una
# corrida cortada no sabe el color de lo que no llego a correr. Se FUSIONA con lo
# anterior: lo que no corrio ahora conserva su color. Se guardan TODAS las vigias
# que corrieron (verdes y rojas), no solo las rojas.
