if not hubo_corte and ultima:
    partes = ultima[0].strip().split()
    if (len(partes) >= 9
            and partes[0] == "bateria"
            and partes[1] == "en"
            and partes[2] == "paralelo:"
            and partes[-3:] == ["cortados", "por", "tiempo"]):
        try:
            if int(partes[-4]) > 0:
                hubo_corte = True
        except ValueError:
            pass
if not hubo_corte:
    try:
        ruta_colores = os.path.join(raiz, "memoria", ".colores_de_antes.json")
        os.makedirs(os.path.dirname(ruta_colores), exist_ok=True)
        colores_nuevos = dict(colores_de_antes)
        for linea in salida.splitlines():
            linea = linea.strip()
            if linea.startswith(("PASSED", "FAILED", "ERROR")):
                archivo = linea.split("::")[0].strip()
                for prefijo in ("PASSED", "FAILED", "ERROR"):
                    if archivo.startswith(prefijo):
                        archivo = archivo[len(prefijo):].strip()
                        break
                archivo = archivo.split(" - ")[0].strip()
                archivo = archivo.replace("\\", "/")
                if not archivo:
                    continue
                if linea.startswith("PASSED"):
                    colores_nuevos[archivo] = "verde"
                else:
                    colores_nuevos[archivo] = "roja"
        with open(ruta_colores, "w", encoding="utf-8") as f:
            json.dump(colores_nuevos, f)
    except Exception:
        pass

