def rojas_que_frenan(rojas_ahora, guardadas, declaradas, colores_de_antes):
    def _como_lista(x):
        return x if isinstance(x, list) else []
    rojas_ahora = _como_lista(rojas_ahora)
    guardadas = _como_lista(guardadas)
    declaradas = _como_lista(declaradas)
    if not isinstance(colores_de_antes, dict):
        colores_de_antes = {}
    frenan = []
    for roja in rojas_ahora:
        if roja not in guardadas:
            continue
        if roja in declaradas:
            continue
        if colores_de_antes.get(roja) == "roja":
            continue
        frenan.append(roja)
    return frenan
